// Choose a filename or NULL as allowed. If non-NULL, use a fuzzer-provided temp file path.
// Limit create_mode to either -1 or a sane small mode like 0600.
int choice = (int)(*FUZZ_PARAM(unsigned int) % 3);
const char *fname = nullptr;
int create_mode = -1;
if (choice == 0) {
    // Open with NULL fname (intended for parse-from-memory use later)
    fname = nullptr;
    create_mode = -1;
} else if (choice == 1) {
    fname = FUZZ_PARAM_FILENAME();
    create_mode = -1; // don't force-create
} else {
    fname = FUZZ_PARAM_FILENAME();
    create_mode = 0600; // typical creation mode
}
CONFIG_REC *rec = config_open(fname, create_mode);
// Must check for NULL per API guidance.
if (!rec) { FUZZ_BAIL(); }
// Track attributes for downstream validation.
FUZZ_SET_ATTR_INT(rec, "closed", 0);
FUZZ_SET_ATTR_INT(rec, "has_fname", fname ? 1 : 0);
FUZZ_SET_ATTR_INT(rec, "create_mode", create_mode);
if (fname) { FUZZ_SET_ATTR_STR(rec, "fname", fname); }
// Output: persistent CONFIG_REC* managed by the API.
// Validation: Ensures non-NULL return, tracks filename presence and closed state for later APIs.

// config_close requires a CONFIG_REC obtained from config_open and not yet closed.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
config_close(rec);
// Mark as closed to prevent double-close and downstream use.
FUZZ_SET_ATTR_INT(rec, "closed", 1);
// Validation: Enforces single-close via attribute; object is not returned, avoiding use-after-free.

// Must operate on an open CONFIG_REC
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
// Randomly choose a new filename or NULL per signature.
int use_null = (int)(*FUZZ_PARAM(unsigned int) & 1u);
const char *new_fname = use_null ? (const char *)nullptr : FUZZ_PARAM_FILENAME();
// Choose a small set of create_mode values to cover behaviors
int mode_choice = (int)(*FUZZ_PARAM(unsigned int) % 3);
int new_mode = (mode_choice == 0 ? -1 : (mode_choice == 1 ? 0600 : 0644));
config_change_file_name(rec, new_fname, new_mode);
// Update tracked attributes
FUZZ_SET_ATTR_INT(rec, "has_fname", new_fname ? 1 : 0);
FUZZ_SET_ATTR_INT(rec, "create_mode", new_mode);
if (new_fname) { FUZZ_SET_ATTR_STR(rec, "fname", new_fname); }
// Validation: Ensures record is open and updates filename/mode attributes; returns rec for continued use.

// Requires an open CONFIG_REC with a filename set.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(rec, "has_fname")) { FUZZ_BAIL(); }
// Invoke parse; return value semantics are undocumented, so we don't assert.
(void)config_parse(rec);
// Validation: Enforces presence of filename and open state; returns rec for further operations.

// Requires an open CONFIG_REC; filename is not required for parse_data.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
std::string data = FUZZ_PARAM_STR();
std::string input_name = FUZZ_PARAM_STR();
( void )config_parse_data(rec, data.c_str(), input_name.c_str());
// Validation: Exercises in-memory parse path; preserves rec for further use.

// Requires an open CONFIG_REC. If fname is NULL, a filename must be set.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
int pass_null = (int)(*FUZZ_PARAM(unsigned int) & 1u);
const char *fname = pass_null ? (const char *)nullptr : FUZZ_PARAM_FILENAME();
int mode_choice = (int)(*FUZZ_PARAM(unsigned int) % 3);
int create_mode = (mode_choice == 0 ? -1 : (mode_choice == 1 ? 0600 : 0644));
if (!fname && !FUZZ_GET_ATTR_INT(rec, "has_fname")) { FUZZ_BAIL(); }
( void )config_write(rec, fname, create_mode);
// If we wrote with a non-NULL fname, update tracked attributes accordingly.
if (fname) {
    FUZZ_SET_ATTR_INT(rec, "has_fname", 1);
    FUZZ_SET_ATTR_STR(rec, "fname", fname);
    FUZZ_SET_ATTR_INT(rec, "create_mode", create_mode);
}
// Validation: Enforces required preconditions on filename presence; keeps rec available.

// Lookup string from config at section/key. Requires open CONFIG_REC.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
std::string section = FUZZ_PARAM_STR();
std::string key = FUZZ_PARAM_STR();
std::string defval = FUZZ_PARAM_STR();
char *val = config_get_str(rec, section.c_str(), key.c_str(), defval.c_str());
(void)val; // Ownership/lifetime are undocumented; do not free.
// Validation: Preserves rec; avoids assumptions about returned pointer ownership.

// Integer lookup requires open CONFIG_REC.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
std::string section = FUZZ_PARAM_STR();
std::string key = FUZZ_PARAM_STR();
int defval = (int)(*FUZZ_PARAM(unsigned int) % 1000);
int out = config_get_int(rec, section.c_str(), key.c_str(), defval);
(void)out;
// Validation: Simple exercise; no ownership issues; rec is returned for chaining.

// Boolean lookup requires open CONFIG_REC.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
std::string section = FUZZ_PARAM_STR();
std::string key = FUZZ_PARAM_STR();
int defval = (int)(*FUZZ_PARAM(unsigned int) & 1u);
int out = config_get_bool(rec, section.c_str(), key.c_str(), defval);
(void)out;
// Validation: Exercises bool retrieval; returns rec for continued use.

// This API expects a list node; enforce via attribute tracking when available.
// If the attribute is missing or indicates non-list, bail to avoid UB.
int is_list = FUZZ_GET_ATTR_INT(node, "node_type_is_list");
if (!is_list) { FUZZ_BAIL(); }
int index = (int)(*FUZZ_PARAM(unsigned int) % 8); // keep small to avoid deep traversals
CONFIG_NODE *child = config_node_nth(node, index);
(void)child; // May be NULL; we don't return it to avoid emitting NULL outputs.
// Validation: Ensures input is a list-type node via attribute and bounds index to a small range.

// Requires a parent node containing children.
int has_children = FUZZ_GET_ATTR_INT(parent, "has_children");
if (!has_children) { FUZZ_BAIL(); }
std::string key = FUZZ_PARAM_STR();
int idx = config_node_index(parent, key.c_str());
(void)idx; // Semantics when not found are undocumented.
// Validation: Uses attribute to require that parent has children; retains parent for reuse.

// Set or update a string value in config. Requires open CONFIG_REC.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
std::string section = FUZZ_PARAM_STR();
std::string key = FUZZ_PARAM_STR();
std::string value = FUZZ_PARAM_STR();
( void )config_set_str(rec, section.c_str(), key.c_str(), value.c_str());
// Validation: Avoids NULL value to stay within documented safe path; returns rec.

// Set or update an integer value. Requires open CONFIG_REC.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
std::string section = FUZZ_PARAM_STR();
std::string key = FUZZ_PARAM_STR();
int value = (int)(*FUZZ_PARAM(unsigned int) % 100000);
( void )config_set_int(rec, section.c_str(), key.c_str(), value);
// Validation: Keeps values within a reasonable range; rec is returned for chaining.

// Set or update a boolean value. Requires open CONFIG_REC.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
std::string section = FUZZ_PARAM_STR();
std::string key = FUZZ_PARAM_STR();
int value = (int)(*FUZZ_PARAM(unsigned int) & 1u);
( void )config_set_bool(rec, section.c_str(), key.c_str(), value);
// Validation: Boolean constrained to 0/1; returns rec for continued operations.

// Find a child node by key under parent. We do not assume parent type beyond being valid.
std::string key = FUZZ_PARAM_STR();
// Invoke; returned node may be NULL per API, we do not output it to avoid NULL outputs.
CONFIG_NODE *child = config_node_find(parent, key.c_str());
(void)child;
// If parent previously had children tracked, keep that attribute; otherwise, mark unknown state.
// Validation: Non-crashing traversal with arbitrary key; parent is preserved for further use.

// Requires valid CONFIG_REC and parent node. Create behavior needs NODE_TYPE_* constants which we don't have,
// so we request lookup-only by passing new_type = -1 to avoid undefined constants.
std::string key = FUZZ_PARAM_STR();
int new_type = -1; // no creation when missing
CONFIG_NODE *sec = config_node_section(rec, parent, key.c_str(), new_type);
(void)sec; // May be NULL if not found; we don't emit it.
// Validation: Safe lookup-only call; preserves rec and parent for chaining.

// Indexed section lookup under parent. Without NODE_TYPE_* constants, keep this as lookup-only.
std::string key = FUZZ_PARAM_STR();
int index = (int)(*FUZZ_PARAM(unsigned int) % 6); // small index range
int new_type = -1; // do not create to avoid relying on unknown enum values
CONFIG_NODE *sec = config_node_section_index(rec, parent, key.c_str(), index, new_type);
(void)sec; // May be NULL; we don't output it.
// Validation: Exercises index-based lookup path while keeping objects valid.

// Traverse using a random path. To guarantee a non-NULL output node, request creation when missing.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
std::string section = FUZZ_PARAM_STR();
CONFIG_NODE *node = config_node_traverse(rec, section.c_str(), /*create=*/1);
if (!node) { FUZZ_BAIL(); }
// Track useful attributes for downstream stubs.
FUZZ_SET_ATTR_INT(node, "has_children", 1); // created/traversed sections generally can contain children
FUZZ_SET_ATTR_STR(node, "path", section.c_str());
// Note: no parent pointer tracked here; this may be a root/section path.
// Validation: Ensures non-NULL via create=1 and marks attributes to aid other APIs.

// This API requires that node represents a list. Enforce via attribute set by earlier creators.
int is_list = FUZZ_GET_ATTR_INT(node, "node_type_is_list");
if (!is_list) { FUZZ_BAIL(); }
char **arr = config_node_get_list(node);
(void)arr; // Ownership undocumented; do not free.
// Validation: Enforces list-type precondition via attribute and preserves node.

// Append values into a list node. Enforce node being a list via attribute.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
int is_list = FUZZ_GET_ATTR_INT(node, "node_type_is_list");
if (!is_list) { FUZZ_BAIL(); }
// Build a small NULL-terminated C-string array; strings live long enough for the call.
std::string s1 = FUZZ_PARAM_STR();
std::string s2 = FUZZ_PARAM_STR();
std::string s3 = FUZZ_PARAM_STR();
char *arr[4];
int n = (int)(*FUZZ_PARAM(unsigned int) % 3) + 1; // 1..3 entries
arr[0] = (char*)s1.c_str();
arr[1] = (n >= 2 ? (char*)s2.c_str() : (char*)nullptr);
arr[2] = (n >= 3 ? (char*)s3.c_str() : (char*)nullptr);
arr[n] = nullptr; // explicit NULL terminator at correct position
config_node_add_list(rec, node, (char**)arr);
// Validation: Proper NULL-terminated array; preserves rec/node for further use.

// Retrieve a string value by key from the parent node.
std::string key = FUZZ_PARAM_STR();
std::string defv = FUZZ_PARAM_STR();
char *out = config_node_get_str(parent, key.c_str(), defv.c_str());
(void)out; // lifetime/ownership unknown
// Validation: Safe lookup with default; parent retained.

// Retrieve an integer value by key from the parent node.
std::string key = FUZZ_PARAM_STR();
int defv = (int)(*FUZZ_PARAM(unsigned int) % 10000);
int out = config_node_get_int(parent, key.c_str(), defv);
(void)out;
// Validation: Simple numeric lookup; parent preserved.

// Retrieve a boolean (int) value by key from the parent node.
std::string key = FUZZ_PARAM_STR();
int defv = (int)(*FUZZ_PARAM(unsigned int) & 1u);
int out = config_node_get_bool(parent, key.c_str(), defv);
(void)out;
// Validation: Boolean constrained to 0/1; parent retained.

// Set or update a string value at node level. Use key+value (both non-NULL) for general safety.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
std::string key = FUZZ_PARAM_STR();
std::string val = FUZZ_PARAM_STR();
config_node_set_str(rec, parent, key.c_str(), val.c_str());
// Mark that parent now has (or still has) children/values
FUZZ_SET_ATTR_INT(parent, "has_children", 1);
// Validation: Uses well-defined combination (key && value) and tracks child presence.

// Set or update an integer value at node level with a non-negative, bounded value.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
std::string key = FUZZ_PARAM_STR();
int val = (int)(*FUZZ_PARAM(unsigned int) % 100000);
config_node_set_int(rec, parent, key.c_str(), val);
FUZZ_SET_ATTR_INT(parent, "has_children", 1);
// Validation: Avoids overflowy extremes; marks parent as having children.

// Set or update a boolean value (as int) at node level.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
std::string key = FUZZ_PARAM_STR();
int val = (int)(*FUZZ_PARAM(unsigned int) & 1u);
config_node_set_bool(rec, parent, key.c_str(), val);
FUZZ_SET_ATTR_INT(parent, "has_children", 1);
// Validation: Boolean constrained to 0/1; parent retained.

// Remove a specific child node from its parent. Enforce correct parent-child relationship via attribute.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
// We require that the node's recorded parent matches the provided parent to avoid UB.
void *recorded_parent = FUZZ_GET_ATTR_PTR(node, "parent");
if (recorded_parent != (void*)parent) { FUZZ_BAIL(); }
config_node_remove(rec, parent, node);
// After removal, parent still exists; the removed node is dropped by not returning it.
// Validation: Prevents removing non-children by checking tracked parent pointer.

// Remove an element at index from a list node. Enforce node being a list via attribute.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
int is_list = FUZZ_GET_ATTR_INT(node, "node_type_is_list");
if (!is_list) { FUZZ_BAIL(); }
int index = (int)(*FUZZ_PARAM(unsigned int) % 8); // small index range
config_node_list_remove(rec, node, index);
// Validation: Index kept small and list-type enforced; node and rec preserved.

// Clear all data inside a node but keep the node itself.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
config_node_clear(rec, node);
// After clear, conservatively mark that node may have no children.
FUZZ_SET_ATTR_INT(node, "has_children", 0);
// Validation: Ensures record is open; attributes updated to reflect empty node.

// Remove all nodes from the configuration record.
if (FUZZ_GET_ATTR_INT(rec, "closed")) { FUZZ_BAIL(); }
config_nodes_remove_all(rec);
// Mark global and per-rec attributes to indicate invalidation of previous nodes.
FUZZ_SET_ATTR_INT_GLOBAL("config_nodes_cleared", 1);
FUZZ_SET_ATTR_INT(rec, "nodes_invalidated", 1);
// Validation: Ensures open rec; signals to downstream that node pointers may be invalid.

