import os
import random
import string
from typing import List

# Target data type: filesystem path
# Fuzzer stubs call FUZZ_PARAM_FILENAME() to obtain a path to a temp file that the
# harness will create containing our provided buffer. Our job is to generate the
# initial file content (bytes) that should be valid/interesting for the Irssi
# configuration APIs, as these stubs exercise config_open/change_file_name/config_write.
#
# To maximize valid code paths, generate syntactically valid Irssi config text with
# variability: blocks, lists, key/value pairs, integers, booleans, comments, and
# nesting. Keep under 4096 bytes.

BOOL_WORDS = ["on", "off", "yes", "no", "true", "false", "1", "0"]

SECTION_NAMES = [
    "settings", "servers", "channels", "aliases", "themes", "logs",
    "statusbar", "scripts", "keyboard", "formats", "chatnets"
]

KEY_NAMES = [
    "nick", "real_name", "user_name", "auto_connect", "hostname", "port",
    "use_ssl", "password", "autojoin", "reconnect_time", "timestamps",
    "notify_levels", "theme", "scrollback_lines", "window_auto_renumber",
]

CHANNEL_LIKE = ["#irssi", "#test", "#dev", "#random", "#fuzz", "#unicode-ä"]
NETWORK_LIKE = ["freenode", "libera", "oftc", "example", "testnet"]
NICK_LIKE = ["alice", "bob", "carol", "dave", "mallory", "trent"]
HOST_LIKE = ["irc.example.org", "chat.libera.chat", "localhost", "::1", "127.0.0.1"]


def _rand_choice(rng: random.Random, items: List[str]) -> str:
    return rng.choice(items)


def _rand_int(rng: random.Random, lo: int, hi: int) -> int:
    return rng.randint(lo, hi)


def _rand_bool_word(rng: random.Random) -> str:
    return _rand_choice(rng, BOOL_WORDS)


def _rand_ident(rng: random.Random, base_pool: List[str]) -> str:
    # Sometimes pick from pool, sometimes synthesize
    if rng.random() < 0.7:
        return _rand_choice(rng, base_pool)
    # Synthesize identifier: letters, digits, underscore, dash
    length = _rand_int(rng, 3, 14)
    chars = string.ascii_letters + string.digits + "_-"
    return ''.join(rng.choice(chars) for _ in range(length))


def _quote_if_needed(s: str) -> str:
    # Irssi config accepts unquoted for many tokens; include quotes for variety
    special = any(c.isspace() or c in '"#;{}()' for c in s)
    if special:
        return '"' + s.replace('"', '\\"') + '"'
    return s


def _emit_comment(rng: random.Random) -> str:
    style = rng.choice(["#", ";"])  # permissible comment starters
    words = ["generated", "by", "seeded", "generator", str(_rand_int(rng, 0, 9999))]
    return f"{style} {' '.join(words)}\n"


def _emit_kv(rng: random.Random) -> str:
    key = _rand_ident(rng, KEY_NAMES)
    t = rng.random()
    if t < 0.35:
        # string value
        val_choice = rng.choice([
            _rand_choice(rng, NICK_LIKE),
            _rand_choice(rng, CHANNEL_LIKE),
            _rand_choice(rng, HOST_LIKE),
            _rand_choice(rng, NETWORK_LIKE),
            "foo bar",  # contains space to exercise quotes
        ])
        value = _quote_if_needed(val_choice)
    elif t < 0.7:
        # integer value
        value = str(_rand_int(rng, -5, 65535))
    else:
        # boolean value words
        value = _rand_bool_word(rng)
    return f"{key} = {value};\n"


def _emit_list(rng: random.Random, name: str, values: List[str]) -> str:
    # Irssi list syntax: name = { item, item, ... };
    # Also sometimes as: name = ( item item ); but brace style is common.
    style = rng.choice(["braces", "parens"]) if rng.random() < 0.6 else "braces"
    items = []
    n = _rand_int(rng, 0, 6)
    for _ in range(n):
        v = _quote_if_needed(_rand_choice(rng, values))
        items.append(v)
    if style == "parens":
        # Paren style uses space separators and trailing semicolon
        inside = " ".join(items)
        return f"{name} = ( {inside} );\n"
    else:
        # Brace style uses comma separators
        inside = ", ".join(items)
        return f"{name} = {{ {inside} }};\n"


def _emit_block(rng: random.Random, name: str, body: str) -> str:
    return f"{name} {{\n{body}}}\n"


def _emit_servers_block(rng: random.Random) -> str:
    # Typical Irssi servers block with list of server sections
    entries = []
    m = _rand_int(rng, 1, 4)
    for _ in range(m):
        body = []
        body.append(f"address = {_quote_if_needed(_rand_choice(rng, HOST_LIKE))};\n")
        body.append(f"port = {_rand_int(rng, 1, 65535)};\n")
        if rng.random() < 0.7:
            body.append(f"chatnet = {_quote_if_needed(_rand_choice(rng, NETWORK_LIKE))};\n")
        if rng.random() < 0.5:
            body.append(f"use_ssl = {_rand_bool_word(rng)};\n")
        if rng.random() < 0.4:
            body.append(f"password = {_quote_if_needed('pass' + str(_rand_int(rng, 0, 9999)))};\n")
        if rng.random() < 0.5:
            body.append(f"autojoin = {_quote_if_needed(','.join(rng.sample(CHANNEL_LIKE, k=_rand_int(rng, 1, min(3, len(CHANNEL_LIKE))))))};\n")
        entry = _emit_block(rng, "server", "".join(body))
        entries.append(entry)
    return _emit_block(rng, "servers", "".join(entries))


def _emit_channels_block(rng: random.Random) -> str:
    entries = []
    m = _rand_int(rng, 1, 4)
    for _ in range(m):
        body = []
        body.append(f"name = {_quote_if_needed(_rand_choice(rng, CHANNEL_LIKE))};\n")
        if rng.random() < 0.7:
            body.append(f"chatnet = {_quote_if_needed(_rand_choice(rng, NETWORK_LIKE))};\n")
        if rng.random() < 0.5:
            body.append(f"auto_join = {_rand_bool_word(rng)};\n")
        if rng.random() < 0.3:
            body.append(f"password = {_quote_if_needed('p' + str(_rand_int(rng, 0, 9999)))};\n")
        entries.append(_emit_block(rng, "channel", "".join(body)))
    return _emit_block(rng, "channels", "".join(entries))


def _emit_settings_block(rng: random.Random) -> str:
    lines = []
    # A mix of kvs and sub-blocks
    for _ in range(_rand_int(rng, 2, 6)):
        if rng.random() < 0.2:
            lines.append(_emit_comment(rng))
        lines.append(_emit_kv(rng))
    # Include a list value
    lines.append(_emit_list(rng, "autolog_items", CHANNEL_LIKE))
    return _emit_block(rng, "settings", "".join(lines))


def _emit_chatnets_block(rng: random.Random) -> str:
    entries = []
    n = _rand_int(rng, 1, 3)
    for _ in range(n):
        name = _rand_choice(rng, NETWORK_LIKE)
        body = []
        body.append(f"type = irc;\n")
        if rng.random() < 0.7:
            body.append(f"nick = {_quote_if_needed(_rand_choice(rng, NICK_LIKE))};\n")
        if rng.random() < 0.5:
            body.append(f"real_name = {_quote_if_needed('Real ' + _rand_choice(rng, NICK_LIKE))};\n")
        if rng.random() < 0.5:
            body.append(f"autosendcmd = {_quote_if_needed('/join ' + _rand_choice(rng, CHANNEL_LIKE))};\n")
        entries.append(_emit_block(rng, f"{name}", "".join(body)))
    return _emit_block(rng, "chatnets", "".join(entries))


def _emit_root(rng: random.Random) -> str:
    parts = []
    # Optional header comments
    for _ in range(_rand_int(rng, 0, 3)):
        parts.append(_emit_comment(rng))
    # Assemble several top-level sections with random ordering
    builders = [
        _emit_settings_block,
        _emit_servers_block,
        _emit_channels_block,
        _emit_chatnets_block,
    ]
    rng.shuffle(builders)
    for b in builders:
        if rng.random() < 0.85:  # include most but not necessarily all
            parts.append(b(rng))
            if rng.random() < 0.3:
                parts.append("\n")
    # Trailing miscellaneous kvs at root (Irssi allows some simple keys at root)
    if rng.random() < 0.6:
        for _ in range(_rand_int(rng, 1, 4)):
            parts.append(_emit_kv(rng))
    return "".join(parts)


def _trim_to_limit(s: str, limit: int = 4096) -> str:
    if len(s) <= limit:
        return s
    # Try to trim at section boundary to keep syntax valid
    idx = s.rfind("}\n", 0, limit)
    if idx != -1:
        return s[: idx + 2]
    # Fallback hard trim; also ensure last char ends with newline
    t = s[:limit]
    if not t.endswith("\n"):
        t = t.rsplit("\n", 1)[0] + "\n" if "\n" in t else t[:-1] + "\n"
    return t


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Randomly choose between a non-empty realistic config and minimal valid configs
    choice = rng.random()
    if choice < 0.15:
        # Minimal valid: empty file or only comment
        if rng.random() < 0.5:
            text = "\n"
        else:
            text = _emit_comment(rng)
    elif choice < 0.3:
        # Small single-block config
        text = _emit_settings_block(rng)
    else:
        # Full multi-section config
        text = _emit_root(rng)
    text = _trim_to_limit(text, 4096)
    # Ensure file ends with newline for parsers that expect it
    if not text.endswith("\n"):
        text += "\n"
    return text.encode("utf-8", errors="strict")

import os
import random
import struct
from typing import List

# Generator for initial interesting buffers for an Irssi configuration file context.
# Focus: Provide valid/near-valid Irssi config syntax while varying structure to
# exercise config_open (which may subsequently be used by parse APIs).
# No I/O; just return bytes up to 4096.

IDENT_CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-"

def _r(rand: random.Random, a: int, b: int) -> int:
    return rand.randint(a, b)

def _ident(rand: random.Random, min_len=1, max_len=12) -> str:
    n = _r(rand, min_len, max_len)
    return ''.join(rand.choice(IDENT_CHARS) for _ in range(n))

def _string_literal(rand: random.Random) -> str:
    # Irssi config strings are typically unquoted for simple tokens; support both.
    # Occasionally include spaces and escaped chars inside quotes.
    if rand.random() < 0.55:
        # unquoted simple token
        token_chars = IDENT_CHARS + ".:/@#"
        n = _r(rand, 1, 24)
        return ''.join(rand.choice(token_chars) for _ in range(n))
    # quoted
    n = _r(rand, 0, 40)
    body = []
    for _ in range(n):
        ch = rand.choice([' ', '\t', '\\', '"', '\n', '\r'] + list(IDENT_CHARS) + list(".-:/@#"))
        if ch in ['\\', '"', '\n', '\r', '\t']:
            # escape special
            mapping = {'\\': '\\\\', '"': '\\"', '\n': '\\n', '\r': '\\r', '\t': '\\t'}
            body.append(mapping.get(ch, ch))
        else:
            body.append(ch)
    return '"' + ''.join(body) + '"'

def _bool_val(rand: random.Random) -> str:
    return rand.choice(["yes", "no", "true", "false", "on", "off", "1", "0"])

def _int_val(rand: random.Random) -> str:
    # mix decimal, hex, with optional signs
    if rand.random() < 0.2:
        return str(_r(rand, -5, 5))
    if rand.random() < 0.3:
        return hex(_r(rand, 0, 1 << _r(rand, 4, 16)))
    return str(_r(rand, 0, 10_000))

def _kv(rand: random.Random) -> str:
    key = _ident(rand)
    # choose value type: string/int/bool/list-inline/simple
    t = rand.random()
    if t < 0.45:
        val = _string_literal(rand)
    elif t < 0.65:
        val = _int_val(rand)
    elif t < 0.8:
        val = _bool_val(rand)
    else:
        # inline list-like representation used in many irssi configs: (a b c)
        cnt = _r(rand, 0, 6)
        items = [_string_literal(rand) for _ in range(cnt)]
        val = '(' + ' '.join(items) + ')'
    end = ';'
    return f"{key} = {val}{end}\n"

def _list_block(rand: random.Random, key: str, entries: List[str]) -> str:
    # list of blocks: key = ( { .. } { .. } )
    pieces = [f"{key} = (\n"]
    for e in entries:
        pieces.append("  {\n")
        pieces.append(e)
        pieces.append("  }\n")
    pieces.append(")\n")
    return ''.join(pieces)

def _simple_block(rand: random.Random, key: str, body: str) -> str:
    return f"{key} = {{\n{body}}}\n"

def _make_servers(rand: random.Random) -> str:
    # Typical Irssi config: servers = ( { address = "irc.libera.chat"; chatnet = "libera"; port = 6697; use_ssl = yes; } )
    entries = []
    count = _r(rand, 0, 4)
    for _ in range(count):
        lines = []
        lines.append(f"address = {_string_literal(rand)};\n")
        if rand.random() < 0.7:
            lines.append(f"chatnet = {_string_literal(rand)};\n")
        if rand.random() < 0.8:
            lines.append(f"port = {_int_val(rand)};\n")
        if rand.random() < 0.6:
            lines.append(f"use_ssl = {_bool_val(rand)};\n")
        if rand.random() < 0.4:
            lines.append(f"ssl_verify = {_bool_val(rand)};\n")
        # Random extra kvs
        for _i in range(_r(rand, 0, 3)):
            lines.append(_kv(rand))
        entries.append('    ' + ''.join(lines).replace('\n', '\n    ').rstrip() + '\n')
    return _list_block(rand, "servers", entries)

def _make_chatnets(rand: random.Random) -> str:
    entries = []
    count = _r(rand, 0, 3)
    for _ in range(count):
        lines = []
        lines.append(f"name = {_string_literal(rand)};\n")
        if rand.random() < 0.7:
            lines.append(f"type = {_string_literal(rand)};\n")
        if rand.random() < 0.5:
            lines.append(f"nick = {_string_literal(rand)};\n")
        for _i in range(_r(rand, 0, 2)):
            lines.append(_kv(rand))
        entries.append('    ' + ''.join(lines).replace('\n', '\n    ').rstrip() + '\n')
    return _list_block(rand, "chatnets", entries)

def _make_channels(rand: random.Random) -> str:
    entries = []
    count = _r(rand, 0, 6)
    for _ in range(count):
        lines = []
        lines.append(f"name = {_string_literal(rand)};\n")
        if rand.random() < 0.8:
            lines.append(f"chatnet = {_string_literal(rand)};\n")
        if rand.random() < 0.5:
            lines.append(f"autojoin = {_bool_val(rand)};\n")
        entries.append('    ' + ''.join(lines).replace('\n', '\n    ').rstrip() + '\n')
    return _list_block(rand, "channels", entries)

def _make_settings(rand: random.Random) -> str:
    # settings = { core = { real_name = "..."; ... }; "fe-text" = { ... }; }
    blocks = []
    # core block
    core_lines = []
    if rand.random() < 0.8:
        core_lines.append(f"real_name = {_string_literal(rand)};\n")
    if rand.random() < 0.8:
        core_lines.append(f"user_name = {_string_literal(rand)};\n")
    core_lines.append(f"timestamp_format = {_string_literal(rand)};\n")
    for _ in range(_r(rand, 0, 4)):
        core_lines.append(_kv(rand))
    blocks.append(_simple_block(rand, "core", ''.join('  ' + l for l in core_lines)))

    # fe-text block (optional)
    if rand.random() < 0.7:
        fe_lines = []
        fe_lines.append(f"actlist_sort = {_string_literal(rand)};\n")
        fe_lines.append(f"use_status_window = {_bool_val(rand)};\n")
        for _ in range(_r(rand, 0, 3)):
            fe_lines.append(_kv(rand))
        blocks.append(_simple_block(rand, _string_literal(rand), ''.join('  ' + l for l in fe_lines)))

    return _simple_block(rand, "settings", ''.join(blocks))

def _make_logs(rand: random.Random) -> str:
    entries = []
    count = _r(rand, 0, 3)
    for _ in range(count):
        lines = []
        lines.append(f"auto_open = {_bool_val(rand)};\n")
        lines.append(f"file = {_string_literal(rand)};\n")
        if rand.random() < 0.5:
            lines.append(f"level = {_string_literal(rand)};\n")
        entries.append('    ' + ''.join(lines).replace('\n', '\n    ').rstrip() + '\n')
    return _list_block(rand, "logs", entries)

def _comments(rand: random.Random, n: int) -> str:
    lines = []
    for _ in range(n):
        # Irssi config supports comments with # at beginning of line
        payload = ''.join(rand.choice(IDENT_CHARS + ' .-:/@#') for _ in range(_r(rand, 0, 40)))
        lines.append(f"# {payload}\n")
    return ''.join(lines)

def _top_level(rand: random.Random) -> str:
    parts = []
    # Add header comments
    parts.append(_comments(rand, _r(rand, 0, 3)))

    # Optionally include settings, servers, chatnets, channels, logs in varied order
    builders = [_make_settings, _make_servers, _make_chatnets, _make_channels, _make_logs]
    rand.shuffle(builders)
    for b in builders:
        if rand.random() < 0.85:  # include most, sometimes skip
            parts.append(b(rand))
            parts.append('\n')

    # Add some stray simple key/values at top level
    for _ in range(_r(rand, 0, 5)):
        parts.append(_kv(rand))

    # Trailing comments
    parts.append(_comments(rand, _r(rand, 0, 2)))

    return ''.join(parts)


def generate(seed: int) -> bytes:
    rand = random.Random(seed)

    # Choose one of several profiles to increase variety while staying valid.
    profile = rand.choice([
        "minimal", "typical", "heavy", "lists_only", "comments_only"
    ])

    if profile == "minimal":
        # Very small but valid configuration
        txt = "settings = {\n  core = {\n    real_name = \"Irssi User\";\n  }\n}\n"
    elif profile == "comments_only":
        txt = _comments(rand, _r(rand, 3, 20))
    elif profile == "lists_only":
        # Focus on list parsing paths
        txt = ''.join([
            _make_servers(rand), '\n',
            _make_channels(rand), '\n',
            _make_logs(rand), '\n'
        ])
    elif profile == "typical":
        txt = _top_level(rand)
    else:  # heavy
        # Heavier config with repeated sections to grow tree and indices
        sections = []
        for _ in range(_r(rand, 2, 4)):
            sections.append(_make_settings(rand))
        for _ in range(_r(rand, 1, 3)):
            sections.append(_make_servers(rand))
        for _ in range(_r(rand, 1, 2)):
            sections.append(_make_chatnets(rand))
        for _ in range(_r(rand, 1, 2)):
            sections.append(_make_channels(rand))
        sections.append(_make_logs(rand))
        txt = '\n'.join(sections) + '\n'

    # Ensure size cap
    data = txt.encode('utf-8', errors='replace')
    if len(data) > 4096:
        data = data[:4096]
    return data

import random
import string
from typing import List, Tuple

# Irssi configuration text generator
# Goal: Produce VALID Irssi config syntax that exercises:
# - key/value pairs (strings, ints, bools)
# - blocks (sections) with nested keys
# - lists of values
# - lists of blocks (e.g., channels, servers) with repeated keys
# - comments, whitespace, quoting variations, escapes
# - booleans in multiple textual forms
# - integers in decimal/hex
# - mixed simple and complex paths
# Output should fit within 4096 bytes.

BOOL_FORMS = [
    "yes", "no", "on", "off", "true", "false", "1", "0",
    "YES", "NO", "On", "Off", "True", "False"
]

# Some typical Irssi-like section names and keys
SECTION_NAMES = [
    "settings", "aliases", "servers", "channels", "logs", "fe-settings",
    "replies", "hilights", "keyboard", "perl", "chatnets"
]

KEY_NAMES = [
    "nick", "real_name", "user_name", "server", "port", "ssl", "address",
    "auto_connect", "command", "level", "color", "theme", "log", "away_reason",
    "ctcp_version_reply", "timestamp_format", "reconnect_time"
]

LIST_KEYS = [
    "autosendcmd", "autojoin", "windows", "networks", "ignores", "hilights", "plugins"
]

# Simple strings that show variety in quoting/escapes
SIMPLE_STRINGS = [
    "irssi", "#irssi", "#fuzz", "example", "user", "Test User",
    "C:\\Users\\foo", "/home/test/.irssi", "hello world", "こんにちは", "привет",
    "with\tescapes", "with\"quote", "with\\backslash", "semi;colon", "colon:value"
]

HEX_DIGITS = "0123456789abcdef"


def _rand_bool_text(rng: random.Random) -> str:
    return rng.choice(BOOL_FORMS)


def _rand_int_text(rng: random.Random) -> str:
    # Mix decimal and hex, include edge-ish values
    choice = rng.randint(0, 4)
    if choice == 0:
        return str(rng.randint(-5, 5))
    if choice == 1:
        return str(rng.randint(0, 65535))
    if choice == 2:
        return str(rng.randint(1_000_000, 4_000_000_000))
    if choice == 3:
        val = rng.randint(0, 0xFFFF)
        return f"0x{val:x}"
    # Large hex
    val = rng.getrandbits(32)
    return f"0x{val:x}"


def _rand_simple_value(rng: random.Random) -> str:
    ty = rng.randint(0, 3)
    if ty == 0:
        return _rand_bool_text(rng)
    if ty == 1:
        return _rand_int_text(rng)
    # quoted string
    s = rng.choice(SIMPLE_STRINGS)
    # Occasionally concatenate words
    if rng.random() < 0.3:
        s += " " + rng.choice(SIMPLE_STRINGS)
    # Escape quotes/backslashes appropriately
    s = s.replace("\\", "\\\\").replace("\"", "\\\"")
    return f'"{s}"'


def _rand_key(rng: random.Random) -> str:
    if rng.random() < 0.7:
        return rng.choice(KEY_NAMES)
    # generate identifier-like
    letters = string.ascii_lowercase + string.digits + "_-"
    ln = rng.randint(3, 12)
    return ''.join(rng.choice(letters) for _ in range(ln))


def _rand_section_name(rng: random.Random) -> str:
    if rng.random() < 0.7:
        return rng.choice(SECTION_NAMES)
    return _rand_key(rng)


def _make_comment(rng: random.Random) -> str:
    # Irssi config uses ';' comments (and '#' also commonly accepted); include both
    prefix = rng.choice([';', '#'])
    content = rng.choice([
        " generated by seed ", " config section ", " note ", " utf8 ✓ ", " path "
    ])
    return f"{prefix}{content}{rng.randint(0, 9999)}\n"


def _kv_line(rng: random.Random) -> str:
    key = _rand_key(rng)
    val = _rand_simple_value(rng)
    # Allow both "key = value" and "key = \"value\"" styles; Irssi uses key = value;
    # Termination with optional semicolon is tolerated; include semicolons sometimes
    sep = " = "
    end = ";" if rng.random() < 0.4 else ""
    return f"{key}{sep}{val}{end}\n"


def _list_line(rng: random.Random) -> str:
    key = rng.choice(LIST_KEYS) if rng.random() < 0.7 else _rand_key(rng)
    # Lists can be in [ a, b, c ] or ( a b c ) styles in some parsers; Irssi typically uses = { ... } for blocks
    # Use: key = ( val val val )
    n = rng.randint(0, 6)
    vals = []
    for _ in range(n):
        # For list values, prefer quoted strings to keep spaces
        s = rng.choice(SIMPLE_STRINGS)
        s = s.replace("\\", "\\\\").replace("\"", "\\\"")
        vals.append(f'"{s}"')
    spacing = " " if rng.random() < 0.8 else ""
    inner = (spacing).join(vals)
    return f"{key} = ( {inner} ){';' if rng.random()<0.4 else ''}\n"


def _block(rng: random.Random, name: str, depth: int) -> str:
    # Blocks are like: section = { key = val; nested = { ... }; }
    lines: List[str] = []
    indent = "  " * depth
    lines.append(f"{indent}{name} = {{\n")

    # Inside, mix kv, lists, and nested blocks
    inner_count = rng.randint(2, 8)
    for _ in range(inner_count):
        if rng.random() < 0.15:
            lines.append(indent + "  " + _make_comment(rng))
            continue
        choice = rng.random()
        if choice < 0.55:
            lines.append(indent + "  " + _kv_line(rng))
        elif choice < 0.8 and depth < 2:
            nested_name = _rand_section_name(rng)
            lines.append(_block(rng, nested_name, depth + 1))
        else:
            lines.append(indent + "  " + _list_line(rng))

    lines.append(f"{indent}}}\n")
    return ''.join(lines)


def _server_block(rng: random.Random) -> str:
    # Typical server block list element to exercise repeated keys and booleans/ints
    # servers = ( { address = "irc.example"; port = 6697; ssl = yes; autoconnect = no; } ... )
    kvs = []
    addr = rng.choice([
        "irc.example.org", "irc.libera.chat", "127.0.0.1", "::1", "chat.example",
    ])
    nick = rng.choice(["user", "tester", "fuzzer", "alice", "bob"])
    port = rng.choice([6667, 6697, 7000, rng.randint(1, 65535)])
    ssl = _rand_bool_text(rng)

    def q(s: str) -> str:
        s = s.replace("\\", "\\\\").replace("\"", "\\\"")
        return f'"{s}"'

    kvs.append(f"address = {q(addr)};")
    kvs.append(f"port = {port};")
    kvs.append(f"ssl = {ssl};")
    kvs.append(f"nick = {q(nick)};")
    if rng.random() < 0.6:
        kvs.append(f"password = {q(rng.choice(SIMPLE_STRINGS))};")
    if rng.random() < 0.5:
        kvs.append(f"autoconnect = {_rand_bool_text(rng)};")
    if rng.random() < 0.4:
        kvs.append(f"proxy = {q(rng.choice(['socks5','http','none']))};")

    inner = ' '.join(kvs)
    return f"{{ {inner} }}"


def _servers_section(rng: random.Random) -> str:
    # servers = ( { ... } { ... } ) to exercise list-of-blocks syntax
    n = rng.randint(1, 4)
    blocks = [_server_block(rng) for _ in range(n)]
    space = " "
    return f"servers = ( {space.join(blocks)} );\n"


def _channels_section(rng: random.Random) -> str:
    # channels = ( { name = "#foo"; chatnet = "net"; autojoin = yes; } ... )
    def chan_block() -> str:
        name = rng.choice(["#irssi", "#test", "#fuzz", "&local", "+mode"])
        net = rng.choice(["libera", "oftc", "efnet", "freenode", "local"])  # historical/test values
        aj = _rand_bool_text(rng)
        def q(s: str) -> str:
            s = s.replace("\\", "\\\\").replace("\"", "\\\"")
            return f'"{s}"'
        kv = [f"name = {q(name)};", f"chatnet = {q(net)};", f"autojoin = {aj};"]
        if rng.random() < 0.4:
            kv.append(f"password = {q(rng.choice(SIMPLE_STRINGS))};")
        return "{ " + ' '.join(kv) + " }"

    n = rng.randint(1, 5)
    blocks = [chan_block() for _ in range(n)]
    return f"channels = ( {' '.join(blocks)} );\n"


def _top_level(rng: random.Random) -> str:
    parts: List[str] = []
    # Header comment
    parts.append(_make_comment(rng))

    # Some top-level kv pairs
    for _ in range(rng.randint(1, 4)):
        parts.append(_kv_line(rng))

    # Specific structured sections to reach common code paths
    parts.append(_servers_section(rng))
    parts.append(_channels_section(rng))

    # A couple of generic blocks with nesting
    for _ in range(rng.randint(1, 3)):
        parts.append(_block(rng, _rand_section_name(rng), 0))

    # A list value line
    parts.append(_list_line(rng))

    # Trailing comments and whitespace variety
    for _ in range(rng.randint(0, 2)):
        parts.append(_make_comment(rng))
    if rng.random() < 0.5:
        parts.append("\n")

    text = ''.join(parts)
    # Ensure size <= 4096
    if len(text) > 4096:
        text = text[:4096]
    return text


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    cfg = _top_level(rng)
    return cfg.encode('utf-8', errors='replace')

import random
import string
from typing import List

# Generator for Irssi config path strings and related values
# Targeting stubs that call FUZZ_PARAM_STR for section, key, values.
# We return a single bytes buffer that, when split by the harness, provides
# interesting, valid strings emphasizing Irssi config path grammar including
# lists and nested sections.

MAX_TOTAL = 4096

SECTIONS_BASE = [
    "settings", "servers", "channels", "aliases", "logs", "themes",
    "keyboard", "lag", "ctcp", "dcc", "fe-text", "fe-common", "ui", "core"
]

KEYS = [
    "nick", "user_name", "real_name", "hostname", "port", "ssl", "autoconnect",
    "proxy", "password", "encoding", "theme", "timestamp_format", "autorejoin",
    "autoop", "autovoice", "levels", "target", "awaylog", "flood", "paste_join"
]

BOOL_STRS = ["true", "false", "yes", "no", "on", "off", "1", "0"]

# Irssi config paths may contain list selectors using parentheses, e.g.:
#   servers/(ircnet)/address
#   channels/(ircnet/#irssi)/autojoin
# We'll manufacture diverse shapes and also plain section/key forms.

def rnd_choice(r: random.Random, arr: List[str]) -> str:
    return arr[r.randrange(len(arr))]

def make_atom(r: random.Random, extra: str = "-_.#") -> str:
    # Reasonable atom for names, networks, or channel names
    alpha = string.ascii_letters + string.digits + extra
    n = r.randint(1, 12)
    return ''.join(r.choice(alpha) for _ in range(n))

def make_list_selector(r: random.Random, inner: str) -> str:
    # Wrap inner with parentheses as used by Irssi for lists
    return f"({inner})"

def make_server_selector(r: random.Random) -> str:
    # Common: servers/(ircnet)
    net = make_atom(r)
    return make_list_selector(r, net)

def make_channel_selector(r: random.Random) -> str:
    # Common: channels/(network/#channel)
    net = make_atom(r)
    chan = "#" + make_atom(r, extra="-_")
    return make_list_selector(r, f"{net}/{chan}")

def make_path_simple(r: random.Random) -> str:
    # settings/core or servers/ircnet
    parts = [rnd_choice(r, SECTIONS_BASE), make_atom(r)]
    if r.random() < 0.4:
        parts.append(make_atom(r))
    return "/".join(parts)

def make_path_with_key(r: random.Random) -> str:
    # e.g., settings/core/theme or servers/(ircnet)/address
    base = rnd_choice(r, SECTIONS_BASE)
    if base == "servers" and r.random() < 0.8:
        sel = make_server_selector(r)
        leaf = rnd_choice(r, ["address", "port", "ssl", "proxy", "password"]) if r.random() < 0.7 else make_atom(r)
        return f"servers/{sel}/{leaf}"
    if base == "channels" and r.random() < 0.8:
        sel = make_channel_selector(r)
        leaf = rnd_choice(r, ["autojoin", "key", "mode", "topic"]) if r.random() < 0.7 else make_atom(r)
        return f"channels/{sel}/{leaf}"
    # generic path with 2-3 segments
    segs = [base, make_atom(r)]
    if r.random() < 0.5:
        segs.append(rnd_choice(r, KEYS))
    else:
        segs.append(make_atom(r))
    return "/".join(segs)

def make_section_only(r: random.Random) -> str:
    # A section path suitable for config_node_traverse/create
    base = rnd_choice(r, SECTIONS_BASE)
    if base in ("servers", "channels") and r.random() < 0.9:
        sel = make_server_selector(r) if base == "servers" else make_channel_selector(r)
        if r.random() < 0.7:
            # deeper nesting
            extra = make_atom(r)
            return f"{base}/{sel}/{extra}"
        return f"{base}/{sel}"
    # multi-level blocks
    depth = 1 + r.randint(0, 2)
    parts = [base] + [make_atom(r) for _ in range(depth)]
    return "/".join(parts)

def make_key(r: random.Random) -> str:
    if r.random() < 0.6:
        return rnd_choice(r, KEYS)
    return make_atom(r)

def make_value_str(r: random.Random) -> str:
    # Strings that are likely valid values for many keys
    p = r.random()
    if p < 0.2:
        # boolean-like
        return rnd_choice(r, BOOL_STRS)
    if p < 0.45:
        # integer-like
        return str(r.randint(0, 100000))
    if p < 0.7:
        # hostname or address-like
        host = ".".join(make_atom(r, extra="-") for _ in range(r.randint(2, 4)))
        return host
    if p < 0.85:
        # channel name or nick
        return "#" + make_atom(r, extra="-_")
    # arbitrary ascii string
    n = r.randint(1, 24)
    chars = string.ascii_letters + string.digits + " -_./:@"
    return ''.join(r.choice(chars) for _ in range(n))

def make_triplet(r: random.Random) -> List[str]:
    # For get/set APIs expecting: section, key, value/def
    # Ensure section resembles a valid config path (without the final key)
    if r.random() < 0.6:
        section = make_path_simple(r)
    else:
        section = make_path_with_key(r)
        # Remove final leaf to keep section as a container path for setters
        if "/" in section:
            section = section.rsplit("/", 1)[0]
    key = make_key(r)
    val = make_value_str(r)
    return [section, key, val]

def assemble_records(r: random.Random) -> List[str]:
    records: List[str] = []
    # Include several section-only paths for node_traverse and various shapes
    for _ in range(r.randint(2, 4)):
        records.append(make_section_only(r))
    # Include multiple triplets for get/set str/int/bool
    for _ in range(r.randint(3, 6)):
        section, key, val = make_triplet(r)
        records.extend([section, key, val])
    # Add some explicit bool defaults and numeric defaults as standalone values
    for _ in range(r.randint(1, 3)):
        records.append(rnd_choice(r, BOOL_STRS))
        records.append(str(r.randint(0, 1000)))
    return records

def serialize_records(records: List[str]) -> bytes:
    # Use NUL separators so that the fuzzer harness can split safely regardless of content
    # Also prefix with a simple header that hints this is a path-bag
    # Format: b"CFG\0" + join(records with \0) + trailing \0
    payload = b"CFG\0" + b"\0".join(s.encode("utf-8", errors="ignore") for s in records) + b"\0"
    if len(payload) > MAX_TOTAL:
        payload = payload[:MAX_TOTAL]
    return payload

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    records = assemble_records(r)
    return serialize_records(records)
